description:
Design a simple memory system that reads 32-bit data based on a single-bit address input. When the reset signal is inactive, the module initializes a 2-entry memory with a predefined value; specifically, entry 0 is set to 0 and entry 1 is set to a constant hexadecimal value. On each clock edge, the module allows read access to the specified memory entry, outputting the corresponding data. If the reset signal is asserted, the memory retains its previous state.
module top_module(
               // inputs:
                address,
                clock,
                reset_n,

               // outputs:
                readdata
             )
;

code:
module top_module(
               // inputs:
                address,
                clock,
                reset_n,

               // outputs:
                readdata
             )
;output  [ 31: 0] readdata;
  input            address;
  input            clock;
  input            reset_n;

  wire    [ 31: 0] readdata;
  reg     [ 31: 0] mem [0:1];

  assign readdata = mem[address][31:0];

  always @(posedge clock) begin
    if(!reset_n) begin
      mem[0][31:0] <= 32'h00000000;
      mem[1][31:0] <= 32'h51EAE681;
    end else begin
      mem[address][31:0] <= mem[address][31:0];
    end
  end

endmodule

