module traffic_light_controller (
    input clk,
    input reset,
    output reg [1:0] state
);

    typedef enum reg [1:0] {
        GREEN = 2'b00,  // Green state
        YELLOW = 2'b01,  // Yellow state
        RED = 2'b10  // Red state
    } state_t;

    reg [3:0] count;  // Counter to count clock cycles

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= GREEN;
            count <= 4'b0000;
        end else begin
            case (state)
                GREEN: begin
                    if (count == 4'd9) begin
                        state <= YELLOW;
                        count <= 4'b0000;
                    end else begin
                        count <= count + 4'b0001;
                    end
                end

                YELLOW: begin
                    if (count == 4'd2) begin
                        state <= RED;
                        count <= 4'b0000;
                    end else begin
                        count <= count + 4'b0001;
                    end
                end

                RED: begin
                    if (count == 4'd6) begin
                        state <= GREEN;
                        count <= 4'b0000;
                    end else begin
                        count <= count + 4'b0001;
                    end
                end

                default: begin
                    state <= GREEN;
                    count <= 4'b0000;
                end
            endcase
        end
    end
endmodule

