description:
Design a circuit that implements a binary counter with a flag output indicating when the counter has reached a specified maximum value (25,000,000). The counter increments on each rising edge of the clock signal, and upon reaching the maximum, the flag is set high, indicating an overflow event, while the counter resets to zero. The counter can also be reset asynchronously using a low-active reset signal.
module top_module(

	input clk,
	input rst_n,


	output reg flag

);

code:
module top_module(

	input clk,
	input rst_n,


	output reg flag

);parameter MAX_NUM=25000_000;

reg [24:0] counter;







always @ (posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		flag <= 1'b0;
		counter <= 24'b0;
	end
	else if(counter < MAX_NUM - 1'b1) begin
		flag <= 1'b0;
		counter <= counter + 1'b1;
	end
	else begin
		flag <= 1'b1;
		counter <= 24'b0;
	end
end

endmodule

