description:
Implement the Verilog module based on the following description.
Build a 4-bit binary counter with synchronous active high reset and enable signals, and a carry-out output.
// (1) reset: Resets the counter to 4'b0000.
// (2) enable: Enables counting when high.
// (3) q: The value of the counter.
// (4) carry: The carry-out bit.

module top_module(
    input clk,
    input reset,
    input enable,
    output reg [3:0] q,
    output carry);

code:
module top_module(
    input clk,
    input reset,
    input enable,
    output reg [3:0] q,
    output carry
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to 4'b0000
            q <= 4'b0000;
        end else if (enable) begin
            // Counter increments when enabled
            q <= q + 1;
        end
    end

    // Carry-out when counter overflows
    assign carry = enable & (q == 4'b1111);

endmodule

