module top_module(
    input clk,
    input reset_n,
    output reg [5:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous reset: Reset the counter to 6'b000000
            q <= 6'b000000;
        end else begin
            // Increment the counter
            q <= q + 1;
        end
    end

endmodule

