description:
Design a finite state machine (FSM) that manages a simple operation triggered by a start signal. The FSM operates in two states: "Idle" and "Running." Upon receiving the start signal, it transitions from Idle to Running and begins a count up to 499 clock cycles. During the Running state, the output `done` is controlled based on the counter value—specifically, it is set high when the counter is between 50 and 99 cycles. After reaching a count of 499, the FSM returns to Idle, resetting the state and `done` output. This design provides a mechanism for timing control in a sequential operation.
module top_module(
    input clk,
    input start,
    output reg done
);

code:
module top_module(
    input clk,
    input start,
    output reg done
);// Define the states
    parameter Idle = 2'b00;
    parameter Running = 2'b01;

    // Define the state register and initialize to Idle
    reg [1:0] state_reg = Idle;

    // Define the counter for the Running state
    reg [8:0] running_counter = 0;

    always @(posedge clk) begin
        // State transition logic
        case(state_reg)
            Idle: begin
                if(start) begin
                    state_reg <= Running;
                    running_counter <= 0;
                end
            end
            Running: begin
                if(running_counter == 499) begin
                    state_reg <= Idle;
                    done <= 0;
                end else begin
                    if(running_counter < 50) begin
                        done <= 0;
                    end else if(running_counter < 100) begin
                        done <= 1;
                    end else begin
                        done <= 0;
                    end
                    running_counter <= running_counter + 1;
                end
            end
        endcase
    end

endmodule

