module top_module(
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output reg walk_left,
  output reg walk_right,
  output reg aaah
);// Define states
  parameter WALK_LEFT = 2'b00;
  parameter WALK_RIGHT = 2'b01;
  parameter FALL = 2'b10;

  // Define state register and next state logic
  reg [1:0] state, next_state;
  always @ (posedge clk or negedge areset) begin
    if (areset == 0) begin
      state <= WALK_LEFT;
    end else begin
      state <= next_state;
    end
  end

  // Define output logic
  always @ (*) begin
    case (state)
      WALK_LEFT: begin
        walk_left = 1;
        walk_right = 0;
        aaah = 0;
        if (bump_left == 1) begin
          next_state = WALK_RIGHT;
        end else if (ground == 0) begin
          next_state = FALL;
        end else begin
          next_state = WALK_LEFT;
        end
      end
      WALK_RIGHT: begin
        walk_left = 0;
        walk_right = 1;
        aaah = 0;
        if (bump_right == 1) begin
          next_state = WALK_LEFT;
        end else if (ground == 0) begin
          next_state = FALL;
        end else begin
          next_state = WALK_RIGHT;
        end
      end
      FALL: begin
        walk_left = state[0];
        walk_right = state[1];
        aaah = 1;
        if (ground == 1) begin
          next_state = state;
        end else begin
          next_state = FALL;
        end
      end
    endcase
  end
endmodule

