  assign sum = v1_reg_0 + 5'b00001;  // Example addition logic

  // Comparing the values
  always @(*) begin
    if (sum[4] == 1'b1) 
      comp1 = 1'b1;
    else 
      comp1 = 1'b0;
  end

endmodule

