  next_ten = 4'd0; 
  next_one = 4'd0; 
  end else begin 
  if (one == 4'd0) begin 
  next_ten = ten - 4'd1; 
  next_one = 4'd9; 
  end else begin 
  next_ten = ten; 
  next_one = one - 4'd1; 
  end 
  end 
  end 
  assign isFinished = (ten == 4'd0 && one == 4'd0)?1:0; 
 endmodule

